/** SYNTHETIC whole-site artifact publication served by an in-page fake port.
 * Every coordinate, identifier and label is fictional and generated here: no
 * real parcel, CRS origin, building, container or survey. Pins are computed
 * from the generated bytes so the consumer's size and SHA-256 checks run. */
import { box, buildGlb, type SampleGlb } from '../canonical-ifc-visual/standard-glb-sample';
import type { PlanFeatureCollection, SiteSourcePort } from '../../src/lantern/site-artifacts/types';

const POSED = { posesAlreadyApplied: true, applyTransformAgain: false } as const;
/** Already posed in the renderer frame: +X east, +Y up, +Z south, metres. */
const SITE_EXPORT: SampleGlb = {
  asset: { copyright: 'Synthetic site export generated for fixtures; no real place' },
  meshes: [box([-20, -0.2, -16], [24, 0, 14]), box([0, 0, 0], [9, 6.5, 7]), box([14, 0, -9], [18, 3, -5]), box([-12, 0, 6], [-6, 2.6, 8.4])],
  roots: [0, 1, 2, 3],
  nodes: [{ name: 'Terrain', mesh: 0, extras: POSED }, { name: 'Main house shell', mesh: 1, extras: POSED },
    { name: 'Garden house', mesh: 2, extras: POSED }, { name: 'Temporary container', mesh: 3, extras: POSED }],
};
const ENVELOPE: SampleGlb = {
  asset: { copyright: 'Synthetic reference envelope generated for fixtures; no real place' },
  meshes: [box([-0.3, 0, -0.3], [9.3, 7.4, 7.3])],
  roots: [0],
  nodes: [{ name: 'Reference envelope', mesh: 0, extras: POSED }],
};
const ORIGIN = [1000.25, 2000.5, 0] as const;
const ring = (points: readonly (readonly [number, number])[]) => [...points, points[0]!].map(([x, y]) => [ORIGIN[0] + x, ORIGIN[1] + y]);
const PLAN = {
  type: 'FeatureCollection',
  features: [
    { type: 'Feature', properties: { sourceFeatureId: 'syn-feature-parcel' }, geometry: { type: 'Polygon', coordinates: [ring([[-20, -14], [24, -14], [24, 16], [-20, 16]])] } },
    { type: 'Feature', properties: { sourceFeatureId: 'syn-feature-main' }, geometry: { type: 'Polygon', coordinates: [ring([[0, -7], [9, -7], [9, 0], [0, 0]])] } },
    { type: 'Feature', properties: { sourceFeatureId: 'syn-feature-garden' }, geometry: { type: 'Polygon', coordinates: [ring([[14, 5], [18, 5], [18, 9], [14, 9]])] } },
    { type: 'Feature', properties: { sourceFeatureId: 'syn-feature-hedge' }, geometry: { type: 'LineString', coordinates: [[ORIGIN[0] - 18, ORIGIN[1] + 12], [ORIGIN[0] + 6, ORIGIN[1] + 14], [ORIGIN[0] + 22, ORIGIN[1] + 12]] } },
  ],
} as const;

const hex = async (bytes: Uint8Array<ArrayBuffer>) => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))]
  .map(byte => byte.toString(16).padStart(2, '0')).join('');

export const SYNTHETIC_SITE_PIN = { publicationId: 'syn-site-publication', version: 1 } as const;

export function createSyntheticSitePort(delayMs = 120): SiteSourcePort {
  const site = buildGlb(SITE_EXPORT), envelope = buildGlb(ENVELOPE), plan = new TextEncoder().encode(JSON.stringify(PLAN));
  const ready = (async () => {
    const assets = [
      { assetId: 'syn-asset-site', kind: 'default-generated-export', bytes: site, contentType: 'model/gltf-binary' },
      { assetId: 'syn-asset-envelope', kind: 'official-reference-envelope', bytes: envelope, contentType: 'model/gltf-binary' },
      { assetId: 'syn-asset-plan', kind: 'source-plan', bytes: plan, contentType: 'application/geo+json' },
    ];
    const rows = await Promise.all(assets.map(async asset => ({ ...asset, sha256: await hex(asset.bytes) })));
    const publication = {
      schema: 'houseatlas.site-artifact-publication.v1',
      publication: { ...SYNTHETIC_SITE_PIN, immutable: true, artifactAvailability: 'available-with-coverage-gaps', kind: 'authorized-private-preview' },
      nativePublication: { sitePublicationId: null, nativeScope: null, availability: 'incomplete' },
      modelingArtifactAssetId: null,
      siteFrame: { horizontalCRS: 'Fictional local grid (synthetic)', verticalDatum: 'Unknown (synthetic)', unit: 'm', originSource: ORIGIN,
        modelingAxes: ['east', 'north', 'up'], rendererAxes: ['east', 'up', 'south'] },
      assets: rows.map(row => ({ assetId: row.assetId, kind: row.kind, sha256: row.sha256, bytes: row.bytes.byteLength, contentType: row.contentType,
        frame: 'declared-renderer-frame', sourcePoseAlreadyApplied: true, poseAppliedByAssembly: false, href: null,
        storage: { kind: 'synthetic-fixture', libraryFileId: null, version: 0 } })),
      groups: [
        { groupId: 'syn-group-terrain', assetId: 'syn-asset-site', nodeIndices: [0], meshIndices: [0], materialIndices: [], sourceFeatureId: 'syn-feature-parcel',
          sourceGlobalId: null, sourceStoreyLabel: null, defaultVisible: true, coverage: 'Flat generated plate; no terrain heights', provenance: {} },
        { groupId: 'syn-group-main', assetId: 'syn-asset-site', nodeIndices: [1], meshIndices: [1], materialIndices: [], sourceFeatureId: 'syn-feature-main',
          sourceGlobalId: null, sourceStoreyLabel: null, defaultVisible: true, coverage: 'Generated shell block; no roof or floors', provenance: {} },
        { groupId: 'syn-group-garden', assetId: 'syn-asset-site', nodeIndices: [2], meshIndices: [2], materialIndices: [], sourceFeatureId: 'syn-feature-garden',
          sourceGlobalId: null, sourceStoreyLabel: null, defaultVisible: true, coverage: 'Generated block', provenance: {} },
        { groupId: 'syn-group-container', assetId: 'syn-asset-site', nodeIndices: [3], meshIndices: [3], materialIndices: [], sourceFeatureId: 'syn-feature-container',
          sourceGlobalId: null, sourceStoreyLabel: null, defaultVisible: true, coverage: 'Visual context only; placement not reviewed', provenance: {} },
        // Declared hidden by default: the reference layer starts off.
        { groupId: 'syn-group-reference', assetId: 'syn-asset-envelope', nodeIndices: [0], meshIndices: [0], materialIndices: [], sourceFeatureId: null,
          sourceGlobalId: null, sourceStoreyLabel: null, defaultVisible: false, coverage: 'Reference envelope for the main house; hidden by default', provenance: {} },
      ],
      features: [
        { sourceFeatureId: 'syn-feature-parcel', displayName: 'Synthetic parcel', defaultVisible2D: true, defaultVisible3D: true, groupIds: ['syn-group-terrain'],
          sourceGeometryDimensions: 2, sourceGeometryElevation: null, coverage: { mode: '2D outline with flat plate', reason: 'no source heights' } },
        { sourceFeatureId: 'syn-feature-main', displayName: 'Synthetic main house', defaultVisible2D: true, defaultVisible3D: true, groupIds: ['syn-group-main'],
          sourceGeometryDimensions: 3, sourceGeometryElevation: 0, coverage: { mode: 'shell', reason: null } },
        { sourceFeatureId: 'syn-feature-garden', displayName: 'Synthetic garden house', defaultVisible2D: true, defaultVisible3D: true, groupIds: ['syn-group-garden'],
          sourceGeometryDimensions: 3, sourceGeometryElevation: 0, coverage: { mode: 'shell', reason: null } },
        { sourceFeatureId: 'syn-feature-container', displayName: 'Synthetic container', defaultVisible2D: true, defaultVisible3D: true, groupIds: ['syn-group-container'],
          sourceGeometryDimensions: 3, sourceGeometryElevation: null, coverage: { mode: 'visual context', reason: 'placement not reviewed' } },
        { sourceFeatureId: 'syn-feature-hedge', displayName: 'Synthetic hedge line', defaultVisible2D: true, defaultVisible3D: false, groupIds: [],
          sourceGeometryDimensions: 2, sourceGeometryElevation: null, coverage: { mode: '2D-only', reason: 'source height unavailable' } },
      ],
      canonicalHouse: { status: 'absent-awaiting-corrected-canonical', assetId: null, groupIds: [], qualifiedIfcToSiteMatrix: null, provisionalPose: null },
    };
    return { rows, publication };
  })();
  const wait = (signal: AbortSignal) => new Promise<void>((resolve, reject) => {
    const timer = setTimeout(resolve, delayMs);
    signal.addEventListener('abort', () => { clearTimeout(timer); reject(signal.reason); }, { once: true });
  });
  const pinned = (request: { publicationId: string; version: number }) => request.publicationId === SYNTHETIC_SITE_PIN.publicationId && request.version === SYNTHETIC_SITE_PIN.version;
  return {
    selection: SYNTHETIC_SITE_PIN,
    async loadPublication(request) {
      await wait(request.signal);
      if (!pinned(request)) throw new Error('Not the fixture publication');
      return structuredClone((await ready).publication);
    },
    async readArtifact(request) {
      await wait(request.signal);
      const row = (await ready).rows.find(item => item.assetId === request.assetId);
      if (!pinned(request) || !row || row.sha256 !== request.expectedSha256 || row.bytes.byteLength !== request.expectedBytes) throw new Error('Not a fixture asset');
      return row.bytes.slice().buffer;
    },
    async readSourcePlan(request) {
      await wait(request.signal);
      const row = (await ready).rows.find(item => item.assetId === request.assetId);
      if (!pinned(request) || !row || row.sha256 !== request.expectedSha256) throw new Error('Not a fixture plan');
      return JSON.parse(new TextDecoder().decode(row.bytes)) as PlanFeatureCollection;
    },
    subscribeInvalidation: () => () => {},
  };
}
